 "deploy.done.token": "Agent token",
 "deploy.fiddlerWarning": "Close Fiddler before server operations on this PC: it is the system proxy and would intercept them.",
 "deploy.filesWarning": "Already have the vendor server packages extracted? Enter their folders. Otherwise switch a version to download: Relic fetches the ready-made package from the Internet Archive (1.9 GB for 1.6, 2.5 GB for 2.8) after the agent is installed — a 7z extractor is installed on a Linux box when missing; a Windows PC needs 7-Zip.",
 "deploy.intro": "The agent is the small service Relic talks to on the server. Same parameters for both targets.",
 "deploy.net.advHelp": "The PUBLIC (internet) IP that players outside the server's network connect to. Behind a router (the server only has a private address such as 192.168.x.x): put the router's public IP here and forward TCP 21000, UDP 21081 and the agent's TCP port (18080 unless you changed it) to the server — players on the server's own network then need NAT loopback on the router. Empty = the bind IP is advertised: right for a server whose own address is public (a VPS), LAN-only behind a router. An IP that changes? Use the DDNS host name instead.",
 "deploy.net.advHint": "The address handed to clients (dispatch, gateserver): your public IP when players connect over the Internet. Empty = the bind IP.",
 "deploy.net.advHostHint": "For a dynamic WAN IP: a DNS name kept current by a DDNS updater. The agent follows it and re-applies a new address by itself. Use instead of the advertised IP; give players this name as the server address.",
 "deploy.net.advertisedHost": "DDNS host name (optional)",
 "deploy.net.advertisedIp": "Advertised IP (WAN)",
 "deploy.net.auto": "auto",
 "deploy.net.bindHint": "The local IP docker binds on (.env OUTER_IP). Empty = autodetect.",
 "deploy.net.bindIp": "Bind IP (local)",
 "deploy.net.flaskKey": "Flask secret key (optional)",
 "deploy.net.flaskKeyHint": "The secret the login service (sdk) signs its web cookies with. Replaced like the MySQL password when the server still has the vendor's published default. Empty = a random one (a value this server already stores is kept). 8–128 characters: letters, digits, '_' or '-'.",
 "deploy.net.generate": "Generate",
 "deploy.net.keepEnv": "Keep .env settings",
 "deploy.net.keepEnvFetch": "A downloaded server package comes with the vendor's own .env — its ports on 127.0.0.1 and the published passwords — and it is kept as it is: edit that .env on the server before “Prepare the server” to let other machines connect, or leave this off.",
 "deploy.net.keepEnvSub": "The agent leaves each server's own .env as it is: it replaces none of the vendor's published passwords (MySQL root, Flask key — nor the MUIP sign key or the stack internal password) and does not rewrite OUTER_IP.",
 "deploy.net.keepEnvSubLinux": "Leaving it off does not turn it off on a server where it is already on — that is changed under Agent settings.",
 "deploy.net.kept": "kept as it is",
 "deploy.net.keptHint": "“Keep .env settings” is on: the server's own value is kept — nothing is set from here.",
